PARAMS = ['R0','kout','Imax','IC50','gam']
def predict(df, p):
    def solve_one(dose, times):
        times = np.asarray(times, float)
        kin = p['R0']*p['kout']
        def rhs(t, y):
            C = pk_conc(dose, t)
            I = p['Imax']*C**p['gam']/(p['IC50']**p['gam']+C**p['gam'])
            return [kin*(1-I) - p['kout']*y[0]]
        sol = solve_ivp(rhs, (0, times.max()+1e-9), [p['R0']], t_eval=times, rtol=1e-8, atol=1e-8)
        return sol.y[0]
    return per_dose(df, solve_one)

